/* ---------- SHA-256 (works on file:// too) */
function sha256(ascii) {
  const r = (v, a) => (v >>> a) | (v << (32 - a)); const mp = Math.pow, max = mp(2, 32); let res = "", words = [], bitLen = ascii.length * 8;
  let hash = sha256.h = sha256.h || [], k = sha256.k = sha256.k || [], pl = k.length; const isC = {};
  for (let c = 2; pl < 64; c++) { if (!isC[c]) { for (let i = 0; i < 313; i += c) isC[i] = c; hash[pl] = (mp(c, .5) * max) | 0; k[pl++] = (mp(c, 1 / 3) * max) | 0; } }
  ascii += "\x80"; while (ascii.length % 64 - 56) ascii += "\x00";
  for (let i = 0; i < ascii.length; i++) { const j = ascii.charCodeAt(i); if (j >> 8) return; words[i >> 2] |= j << ((3 - i) % 4) * 8; }
  words[words.length] = ((bitLen / max) | 0); words[words.length] = bitLen; hash = hash.slice(0, 8);
  for (let j = 0; j < words.length;) { const w = words.slice(j, j += 16), old = hash; hash = hash.slice(0, 8);
    for (let i = 0; i < 64; i++) { const w15 = w[i - 15], w2 = w[i - 2], a = hash[0], e = hash[4];
      const t1 = hash[7] + (r(e, 6) ^ r(e, 11) ^ r(e, 25)) + ((e & hash[5]) ^ (~e & hash[6])) + k[i] + (w[i] = i < 16 ? w[i] : (w[i - 16] + (r(w15, 7) ^ r(w15, 18) ^ (w15 >>> 3)) + w[i - 7] + (r(w2, 17) ^ r(w2, 19) ^ (w2 >>> 10))) | 0);
      const t2 = (r(a, 2) ^ r(a, 13) ^ r(a, 22)) + ((a & hash[1]) ^ (a & hash[2]) ^ (hash[1] & hash[2]));
      hash = [(t1 + t2) | 0].concat(hash); hash[4] = (hash[4] + t1) | 0; }
    for (let i = 0; i < 8; i++) hash[i] = (hash[i] + old[i]) | 0; }
  for (let i = 0; i < 8; i++) for (let j = 3; j + 1; j--) { const b = (hash[i] >> (j * 8)) & 255; res += (b < 16 ? "0" : "") + b.toString(16); }
  return res;
}
const hashPw = (pw, salt) => sha256(unescape(encodeURIComponent(salt + "::" + pw)));
const salt = () => Array.from({ length: 16 }, () => Math.floor(Math.random() * 36).toString(36)).join("");

/* ---------- auth (local accounts in this browser; optional Supabase) */
let sb = null;
const AUTH = {
  user: null,
  load() { this.user = LS.get("xc_session", null); },
  users() { return LS.get("xc_users", {}); },
  saveUsers(u) { LS.set("xc_users", u); },
  async init() {
    this.load();
    if (CFG.SUPABASE_URL && CFG.SUPABASE_ANON_KEY) {
      try {
        await new Promise((ok, no) => { const s = document.createElement("script"); s.src = "https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2.45.4/dist/umd/supabase.min.js"; s.onload = ok; s.onerror = no; document.head.append(s); });
        sb = window.supabase.createClient(CFG.SUPABASE_URL, CFG.SUPABASE_ANON_KEY);
        const { data } = await sb.auth.getSession();
        const u = data.session && data.session.user;
        this.user = u ? { uid: u.id, name: (u.user_metadata && u.user_metadata.name) || u.email.split("@")[0], email: u.email, mode: "cloud", created: u.created_at, profile: u.user_metadata || {} } : null;
        LS.set("xc_session", this.user);
      } catch (e) { console.warn("Supabase unavailable, using local accounts", e); sb = null; }
    }
  },
  async signup({ name, email, pw, invite }) {
    name = name.trim(); email = email.trim().toLowerCase();
    if (CFG.INVITE_CODE && invite.trim().toUpperCase() !== CFG.INVITE_CODE.toUpperCase()) throw new Error("លេខកូដអញ្ជើញមិនត្រឹមត្រូវ — សុំពីម្ចាស់គេហទំព័រ");
    if (name.length < 2) throw new Error("ឈ្មោះខ្លីពេក");
    if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) throw new Error("Email មិនត្រឹមត្រូវ");
    if (pw.length < 6) throw new Error("ពាក្យសម្ងាត់ត្រូវមានយ៉ាងតិច ៦ តួ");
    if (sb) {
      const { data, error } = await sb.auth.signUp({ email, password: pw, options: { data: { name } } });
      if (error) throw new Error(error.message);
      if (!data.session) throw new Error("✅ បានបង្កើត — សូមពិនិត្យ Email ដើម្បីបញ្ជាក់ ហើយចូលម្តងទៀត");
      this.user = { uid: data.user.id, name, email, mode: "cloud", created: data.user.created_at, profile: { name } };
    } else {
      const U = this.users();
      if (U[email]) throw new Error("Email នេះមានគណនីរួចហើយ — សូមចូល (Login)");
      if (Object.values(U).some(u => u.name.toLowerCase() === name.toLowerCase())) throw new Error("ឈ្មោះនេះមានគេប្រើហើយ — សូមបន្ថែមនាមត្រកូល");
      const s = salt();
      U[email] = { name, email, salt: s, hash: hashPw(pw, s), created: new Date().toISOString(), profile: { emoji: "", bio: "", goal: "" } };
      this.saveUsers(U);
      this.user = { uid: email, name, email, mode: "local", created: U[email].created, profile: U[email].profile };
    }
    LS.set("xc_session", this.user); return this.user;
  },
  async login({ id, pw }) {
    id = id.trim();
    if (sb) {
      if (!id.includes("@")) throw new Error("សូមប្រើ Email ដើម្បីចូល");
      const { data, error } = await sb.auth.signInWithPassword({ email: id.toLowerCase(), password: pw });
      if (error) throw new Error("Email ឬពាក្យសម្ងាត់មិនត្រឹមត្រូវ");
      const u = data.user; this.user = { uid: u.id, name: (u.user_metadata && u.user_metadata.name) || u.email.split("@")[0], email: u.email, mode: "cloud", created: u.created_at, profile: u.user_metadata || {} };
    } else {
      const U = this.users(); const key = id.toLowerCase();
      const rec = U[key] || Object.values(U).find(u => u.name.toLowerCase() === key);
      if (!rec || rec.hash !== hashPw(pw, rec.salt)) throw new Error("ឈ្មោះ/Email ឬពាក្យសម្ងាត់មិនត្រឹមត្រូវ");
      this.user = { uid: rec.email, name: rec.name, email: rec.email, mode: "local", created: rec.created, profile: rec.profile || {} };
    }
    LS.set("xc_session", this.user); return this.user;
  },
  async logout() { if (sb) try { await sb.auth.signOut(); } catch (e) {} this.user = null; LS.del("xc_session"); },
  async updateProfile(patch) {
    const u = this.user; if (!u) return;
    if (patch.name) u.name = patch.name.trim();
    u.profile = Object.assign({}, u.profile, patch.profile || {});
    if (sb) { await sb.auth.updateUser({ data: Object.assign({}, u.profile, { name: u.name }) }); }
    else { const U = this.users(); if (U[u.uid]) { U[u.uid].name = u.name; U[u.uid].profile = u.profile; this.saveUsers(U); } }
    LS.set("xc_session", u);
  },
  async changePw(oldPw, newPw) {
    if (newPw.length < 6) throw new Error("ពាក្យសម្ងាត់ថ្មីត្រូវមានយ៉ាងតិច ៦ តួ");
    if (sb) { const { error } = await sb.auth.updateUser({ password: newPw }); if (error) throw new Error(error.message); return; }
    const U = this.users(), r = U[this.user.uid];
    if (!r || r.hash !== hashPw(oldPw, r.salt)) throw new Error("ពាក្យសម្ងាត់ចាស់មិនត្រឹមត្រូវ");
    r.salt = salt(); r.hash = hashPw(newPw, r.salt); this.saveUsers(U);
  },
  deleteLocal() { const U = this.users(); delete U[this.user.uid]; this.saveUsers(U); LS.del("xc_stats_" + this.user.uid); this.user = null; LS.del("xc_session"); },
};

/* ---------- per-user stats (shared with lesson pages via localStorage) */
const ST = {
  key() { return "xc_stats_" + (AUTH.user ? AUTH.user.uid : "guest"); },
  get() { return Object.assign({ visits: {}, favs: {}, daily: {}, last: null }, LS.get(this.key(), {})); },
  set(s) { LS.set(this.key(), s); },
  addSeconds(sec) { const s = this.get(), k = dayKey(); s.daily[k] = (s.daily[k] || 0) + sec; this.set(s); },
  toggleFav(id) { const s = this.get(); if (s.favs[id]) delete s.favs[id]; else s.favs[id] = Date.now(); this.set(s); return !!s.favs[id]; },
  streak() { const s = this.get(); let n = 0; const d = new Date(); for (;;) { const k = dayKey(d); if ((s.daily[k] || 0) >= 60 || Object.values(s.visits).some(v => (v.days || []).includes(k))) { n++; d.setDate(d.getDate() - 1); } else break; } return n; },
};

