function avatarHtml(u, cls = "") { const p = (u && u.profile) || {}, e = p.emoji; if (p.photo) return `<span class="avatar has-photo ${cls}"><img src="${esc(p.photo)}" alt=""></span>`; return `<span class="avatar xi-skip ${cls}">${e ? esc(e) : esc((u ? u.name : "?").trim().charAt(0).toUpperCase())}</span>`; }
/* ---------- game-style level (XP from study time, courses opened, visits, streak) */
const LV_NAMES = ["អ្នកចាប់ផ្តើម 🌱", "សិស្សឧស្សាហ៍ 📘", "អ្នកស្វែងយល់ 🔍", "អ្នករៀនសកម្ម ⚡", "អ្នកប្រាជ្ញតូច 🎓", "កំពូលអ្នករៀន 🏅", "វីរៈចំណេះដឹង 🦁", "អធិរាជអង្គរ 👑"];
function levelInfo() {
  const s = ST.get(), mins = Math.floor(Object.values(s.daily).reduce((a, b) => a + b, 0) / 60);
  const opened = Object.keys(s.visits).filter(id => byId(id)).length, visits = Object.values(s.visits).reduce((a, v) => a + (v.n || 1), 0), streak = ST.streak();
  let xp = mins + opened * 15 + visits * 3 + streak * 10, lv = 1, need = 100, left = xp;
  while (left >= need) { left -= need; lv++; need = 100 + (lv - 1) * 50; }
  return { xp, lv, cur: left, need, pct: Math.round(left / need * 100), name: LV_NAMES[Math.min(lv, LV_NAMES.length) - 1], mins, opened, visits, streak };
}
function levelCard(L, big) { return `<div class="lvcard ${big ? "big" : ""}"><div class="lv-badge"><small>LEVEL</small><b>${kh(L.lv)}</b></div><div class="lv-body"><b>${L.name}</b><div class="lv-bar"><i style="width:${L.pct}%"></i></div><small>${kh(L.cur)} / ${kh(L.need)} XP · សរុប ${kh(L.xp)} XP</small></div></div>`; }
function checkLevelUp() { if (!AUTH.user) return; const L = levelInfo(), k = "xc_lv_" + AUTH.user.uid, old = LS.get(k, 0); if (old && L.lv > old) toast(`🎉 ឡើង Level ${kh(L.lv)} — ${L.name}!`); if (L.lv !== old) LS.set(k, L.lv); }
function drawUser() {
  const u = AUTH.user;
  $("#loginBtn").classList.toggle("hide", !!u); $("#userBtn").classList.toggle("hide", !u);
  if (u) $("#userBtn").innerHTML = avatarHtml(u, "sm");
}

